SELECT 'датчик «contract-head» ' || fact_gap($1, 'contract-head') || ': сверять заявленное шапкой не с чем' AS detail WHERE NOT fact_fresh($1, 'contract-head') UNION ALL SELECT 'шапка контракта не называет общего числа требований: равенство, которым она себя закрывает, сверять не с чем' WHERE EXISTS (SELECT 1 FROM code_fact f WHERE f.project_id = $1 AND f.kind = 'contract-head' AND f.name = 'шапка · всего требований · не названо') UNION ALL SELECT 'шапка говорит, что требований ' || f.said || ', а в наборе их ' || r.n FROM (SELECT substring(name from 'всего требований · ([0-9]+)$') AS said FROM code_fact WHERE project_id = $1 AND kind = 'contract-head' AND name LIKE 'шапка · всего требований · %') f CROSS JOIN (SELECT count(*)::text AS n FROM project_requirements q JOIN scheme($1) s ON s.role = 'requirement.kind.functional' AND q.kind = s.value WHERE q.project_id = $1) r WHERE f.said IS NOT NULL AND f.said <> r.n
